const t = document.querySelector('#user-visible-hosts table');
if (!t) return '找不到可見主機表';
const ths = [...t.querySelectorAll(':scope > thead > tr > th')];
const names = ths.map(th => th.textContent.trim());
if (names[names.length - 1] !== '群組') return '吸收欄（群組）應在最後一欄，實際順序：' + names.join('、');
const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);
const contentWidth = td => { const r = document.createRange(); r.selectNodeContents(td); return r.getBoundingClientRect().width; };
const rows = [...t.querySelectorAll(':scope > tbody > tr')];
for (let i = 0; i < ths.length - 1; i++) {
  if (ths[i].classList.contains('text-truncate') || rows.some(tr => tr.children[i]?.classList.contains('text-truncate'))) continue;
  const widest = Math.max(contentWidth(ths[i]), ...rows.map(tr => tr.children[i] ? contentWidth(tr.children[i]) : 0));
  const col = ths[i].getBoundingClientRect().width;
  if (col - widest > 2 * rem + 1) return names[i] + ' 欄寬 ' + Math.round(col) + 'px，最寬內容只有 ' + Math.round(widest) + 'px';
}
return null;

