const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);
const cards = [...document.querySelectorAll('.lf-run-status-grid > .lf-card')];
if (cards.length !== 3) return '狀態卡應有 3 張，實際 ' + cards.length;
const heights = cards.map(c => Math.round(c.getBoundingClientRect().height));
if (Math.max(...heights) - Math.min(...heights) > 1) return '三張卡不等高：' + heights.join('/');
for (const c of cards) {
  const actions = c.querySelector('.lf-run-actions');
  if (!actions || actions.getBoundingClientRect().height === 0) continue;
  let prev = actions.previousElementSibling;
  while (prev && prev.getBoundingClientRect().height === 0) prev = prev.previousElementSibling;
  if (!prev) continue;
  const gap = actions.getBoundingClientRect().top - prev.getBoundingClientRect().bottom;
  if (gap > 1.5 * rem) return c.querySelector('.lf-card__title').textContent.trim() + ' 卡的內容與按鈕之間空 ' + Math.round(gap) + 'px';
}
return null;

const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);
const rows = [...document.querySelectorAll('.lf-run-status-grid .lf-kv')].filter(r => r.getBoundingClientRect().height > 0);
if (!rows.length) return '找不到鍵值列';
for (const r of rows) {
  const label = r.querySelector('.lf-kv__label'), value = r.querySelector('.lf-kv__value');
  if (!label || !value || !value.textContent.trim()) continue;
  const range = document.createRange(); range.selectNodeContents(value);
  const rects = [...range.getClientRects()].filter(x => x.width > 0.5);
  if (!rects.length) continue;
  const first = Math.min(...rects.map(x => x.left));
  const gap = first - label.getBoundingClientRect().right;
  if (gap > 2 * rem) return label.textContent.trim() + ' 的值離標籤 ' + Math.round(gap) + 'px';
  const lines = new Map();
  for (const x of rects) { const k = Math.round(x.top); lines.set(k, (lines.get(k) || 0) + x.width); }
  if (lines.size > 1) {
    const lastTop = Math.max(...lines.keys());
    const fs = parseFloat(getComputedStyle(value).fontSize);
    if (lines.get(lastTop) < fs * 1.5) return label.textContent.trim() + ' 的值最後一行只剩一個字：' + value.textContent.trim().slice(-6);
  }
}
return null;

const grids = [...document.querySelectorAll('.lf-kpi-grid')].filter(g => g.getBoundingClientRect().width > 0);
