const row = document.querySelector('main [data-range]').closest('.d-flex');
const kids = [...row.children].filter(k => k.getBoundingClientRect().width > 0);
const rects = kids.map(k => k.getBoundingClientRect());
for (let i = 0; i < rects.length; i++) for (let j = i + 1; j < rects.length; j++) {
  const a = rects[i], b = rects[j];
  if (a.left < b.right - 1 && b.left < a.right - 1 && a.top < b.bottom - 1 && b.top < a.bottom - 1) return '頂部元素互相重疊';
